// Helper Functions for State -> District -> Category Navigation
export const getAllStates = () => {
  return [...new Set(destinationsData.map((d) => d.state))].sort();
};

export const getDistrictsByState = (state) => {
  if (!state || state === "All") {
    return [...new Set(destinationsData.map((d) => d.district))].sort();
  }
  return [
    ...new Set(
      destinationsData
        .filter((d) => d.state.toLowerCase() === state.toLowerCase())
        .map((d) => d.district)
    )
  ].sort();
};

export const getCategories = () => {
  return [
    { id: "all", label: "All Categories", icon: "Sparkles" },
    { id: "heritage", label: "Heritage & Forts", icon: "Landmark" },
    { id: "nature", label: "Nature & Hills", icon: "Mountain" },
    { id: "spiritual", label: "Spiritual & Temples", icon: "Sun" },
    { id: "adventure", label: "Adventure & Treks", icon: "Compass" }
  ];
};

export const getDestinationsByRegion = (region) => {
  if (!region || region === "All") return destinationsData;
  return destinationsData.filter((d) => d.region.toLowerCase() === region.toLowerCase());
};

export const getHiddenGems = () => {
  return destinationsData.filter((d) => d.isHiddenGem);
};

